<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/auth.php';require_admin();require_once __DIR__.'/../includes/db.php';require_post();verify_csrf();$userId=filter_input(INPUT_POST,'user_id',FILTER_VALIDATE_INT);$badgeId=filter_input(INPUT_POST,'badge_id',FILTER_VALIDATE_INT);if(!$userId||!$badgeId){flash('danger','Choose a valid user and badge.');redirect('admin/badges.php');}$earned=date('Y-m-d H:i:s');try{$stmt=$conn->prepare('INSERT INTO `USER_BADGE` (user_id,badge_id,earned_date) VALUES (?,?,?)');$stmt->bind_param('iis',$userId,$badgeId,$earned);$stmt->execute();flash('success','Badge assigned.');}catch(mysqli_sql_exception $exception){if((int)$exception->getCode()===1062){flash('warning','That user already has this badge.');}else{throw $exception;}}redirect('admin/badges.php');
